module multi_8bit (
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output wire [15:0] product
);
    assign product = A * B;
endmodule

module multi_8bit (
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output wire [15:0] product
);
    // Radix-4 Booth, unsigned 8x8: zero-extend B to 10 bits to make it a
    // signed-positive number, giving 5 Booth digits (column 0,2,4,6,8) each
    // in {-2A,-A,0,+A,+2A}. The final sum still equals A*B mod 2^16.
    wire signed [10:0] Ap  = {{3{1'b0}}, A};   // +A
    wire signed [10:0] An  = -Ap;               // -A
    wire signed [10:0] A2p = Ap <<< 1;          // +2A
    wire signed [10:0] A2n = -A2p;              // -2A

    function automatic [10:0] booth_sel;
        input [2:0] g;
        input signed [10:0] ap, an, a2p, a2n;
        begin
            case (g)
                3'b001, 3'b010: booth_sel = ap;
                3'b011:         booth_sel = a2p;
                3'b100:         booth_sel = a2n;
                3'b101, 3'b110: booth_sel = an;
                default:        booth_sel = 11'sd0;
            endcase
        end
    endfunction

    wire [9:0] B_ext = {2'b00, B};   // zero-extend; B_ext[-1] is implicit 0

    wire [2:0] g0 = {B_ext[1], B_ext[0], 1'b0};
    wire [2:0] g1 = {B_ext[3], B_ext[2], B_ext[1]};
    wire [2:0] g2 = {B_ext[5], B_ext[4], B_ext[3]};
    wire [2:0] g3 = {B_ext[7], B_ext[6], B_ext[5]};
    wire [2:0] g4 = {B_ext[9], B_ext[8], B_ext[7]};

    wire signed [10:0] pp0r = booth_sel(g0, Ap, An, A2p, A2n);
    wire signed [10:0] pp1r = booth_sel(g1, Ap, An, A2p, A2n);
    wire signed [10:0] pp2r = booth_sel(g2, Ap, An, A2p, A2n);
    wire signed [10:0] pp3r = booth_sel(g3, Ap, An, A2p, A2n);
    wire signed [10:0] pp4r = booth_sel(g4, Ap, An, A2p, A2n);

    // Sign-extend each PP to 16 bits, then arithmetic-shift to its column
    wire signed [15:0] pp0 = {{5{pp0r[10]}}, pp0r};
    wire signed [15:0] pp1 = {{5{pp1r[10]}}, pp1r} <<< 2;
    wire signed [15:0] pp2 = {{5{pp2r[10]}}, pp2r} <<< 4;
    wire signed [15:0] pp3 = {{5{pp3r[10]}}, pp3r} <<< 6;
    wire signed [15:0] pp4 = {{5{pp4r[10]}}, pp4r} <<< 8;

    assign product = pp0 + pp1 + pp2 + pp3 + pp4;
endmodule

module multi_8bit (
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output wire [15:0] product
);
    // Wallace-tree style: 8 AND-rows of partial products, then column-wise
    // 3:2 compression to two rows, finished by a single carry-propagate add.
    // Written as bit-level expressions to surface the carry-save structure to
    // the synthesizer (vs. a chain of `+` operators).
    wire [15:0] pp [0:7];
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : g_pp
            assign pp[i] = {8'b0, (A & {8{B[i]}})} << i;
        end
    endgenerate

    // First reduction layer: combine rows {0,1,2}, {3,4,5}, {6,7,carry slot}
    // into 6 rows (sum/carry pairs from 3:2 compressors per column).
    wire [15:0] s012, c012, s345, c345;
    assign s012 = pp[0] ^ pp[1] ^ pp[2];
    assign c012 = ((pp[0] & pp[1]) | (pp[1] & pp[2]) | (pp[0] & pp[2])) << 1;
    assign s345 = pp[3] ^ pp[4] ^ pp[5];
    assign c345 = ((pp[3] & pp[4]) | (pp[4] & pp[5]) | (pp[3] & pp[5])) << 1;

    // Second layer: 4 rows {s012, c012, s345, c345} + remaining 2 rows {pp6, pp7}
    // Compress {s012, c012, s345} → (s_a, c_a) and {c345, pp[6], pp[7]} → (s_b, c_b)
    wire [15:0] s_a, c_a, s_b, c_b;
    assign s_a = s012 ^ c012 ^ s345;
    assign c_a = ((s012 & c012) | (c012 & s345) | (s012 & s345)) << 1;
    assign s_b = c345 ^ pp[6] ^ pp[7];
    assign c_b = ((c345 & pp[6]) | (pp[6] & pp[7]) | (c345 & pp[7])) << 1;

    // Third layer: 4 → 2 with one more 3:2 + the leftover row
    wire [15:0] s_c, c_c;
    assign s_c = s_a ^ c_a ^ s_b;
    assign c_c = ((s_a & c_a) | (c_a & s_b) | (s_a & s_b)) << 1;

    // Final CPA: s_c + c_c + c_b
    assign product = s_c + c_c + c_b;
endmodule

module multi_8bit (
    input  wire [ 7:0] A,
    input  wire [ 7:0] B,
    output wire [15:0] product
);
    // Urdhva Tiryagbhyam (Vedic) decomposition: split each operand into two
    // 4-bit halves and sum the 4 cross-products. Lets the synthesizer optimise
    // each 4x4 sub-multiply independently — typically a small but real ADP
    // win at this width.
    wire [3:0] a_l = A[3:0];
    wire [3:0] a_h = A[7:4];
    wire [3:0] b_l = B[3:0];
    wire [3:0] b_h = B[7:4];

    wire [7:0] ll = a_l * b_l;     // bits  [7:0]
    wire [7:0] lh = a_l * b_h;     // bits [11:4]
    wire [7:0] hl = a_h * b_l;     // bits [11:4]
    wire [7:0] hh = a_h * b_h;     // bits [15:8]

    wire [8:0] mid = lh + hl;      // 9 bits to hold carry
    wire [15:0] cross_term = {3'b0, mid, 4'b0};
    wire [15:0] hi    = {hh, 8'b0};
    wire [15:0] lo    = {8'b0, ll};

    assign product = lo + cross_term + hi;
endmodule
